two_asset_duty.source:
language "moriarty/1"; agreement TwoAssetDuty {
asset A = {network: "local", issuer: "i", reference: "A", scale: 0};
asset B = {network: "local", issuer: "i", reference: "B", scale: 0};
action run() {
transfer(A, "alice", "bob", 7);
fee(A, "alice", "treasury", 2);
transfer(A, "bob", "alice", 3);
transfer(B, "alice", "bob", 5);
fee(B, "alice", "treasury", 1);
liability("d", B, "alice", "bob", 9);
discharge("d", 4);
ensures liability_amount("d") == 5;
} }

